pub struct ClassificationResults {
    pub alnum: i32,
    pub alpha: i32,
    pub lower: i32,
    pub upper: i32,
    pub digit: i32,
    pub xdigit: i32,
    pub cntrl: i32,
    pub graph: i32,
    pub space: i32,
    pub blank: i32,
    pub print: i32,
    pub punct: i32,
    pub to_lower: i8,
    pub to_upper: i8,
}

pub fn classify_char(c: i8) -> ClassificationResults {
    let c_char = c as u8 as char;
    ClassificationResults {
        alnum: if c_char.is_ascii_alphanumeric() { 1 } else { 0 },
        alpha: if c_char.is_ascii_alphabetic() { 1 } else { 0 },
        lower: if c_char.is_ascii_lowercase() { 1 } else { 0 },
        upper: if c_char.is_ascii_uppercase() { 1 } else { 0 },
        digit: if c_char.is_ascii_digit() { 1 } else { 0 },
        xdigit: if c_char.is_ascii_hexdigit() { 1 } else { 0 },
        cntrl: if c_char.is_ascii_control() { 1 } else { 0 },
        graph: if !c_char.is_ascii_control() && !c_char.is_ascii_whitespace() { 1 } else { 0 },
        space: if c_char.is_ascii_whitespace() { 1 } else { 0 },
        blank: if c_char == ' ' || c_char == '\t' { 1 } else { 0 },
        print: if !c_char.is_ascii_control() { 1 } else { 0 },
        punct: if !c_char.is_ascii_alphanumeric() && !c_char.is_ascii_whitespace() && !c_char.is_ascii_control() { 1 } else { 0 },
        to_lower: (c_char.to_ascii_lowercase() as u8) as i8,
        to_upper: (c_char.to_ascii_uppercase() as u8) as i8,
    }
}
